<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import StockDashboards from '@/components/StockDashboards.vue'
import AppModal from '@/components/AppModal.vue'
import AppIcon from '@/components/AppIcon.vue'
import ModuleDemoContext from '@/components/ModuleDemoContext.vue'
import {demoMode,request} from '@/services/quality'
import {notify} from '@/services/notify'
import {currentOffice} from '@/services/supportDemo'
import {initialStock,loadStock,saveStock,resetStock,stockTabs,statusLabels,eventLabels,eligible,fefo,today,daysFromNow,type StockState,type StockCommand} from '@/services/stockDemo'
const route=useRoute()
const tab=computed(()=>stockTabs.some(t=>t[0]===route.query.tab)?String(route.query.tab):'overview')
const title=computed(()=>stockTabs.find(t=>t[0]===tab.value)![1])
const emptyStock=():StockState=>({revision:0,products:[],locations:[],lots:[],events:[]})
const loading=ref(false),allowed=ref(demoMode),operationKey=ref(''),editingRevision=ref(0)
const state=ref<StockState>(demoMode?initialStock():emptyStock()),error=ref(''),notice=ref(''),search=ref(''),page=ref(1),scan=ref(''),scanResult=ref('')
const open=ref(false),detail=ref(false),restoring=ref(false),command=ref<StockCommand>('receipt'),dialogError=ref(''),busy=ref(false),confirmed=ref(false)
const form=ref({name:'',code:'',unit:'Boîte',threshold:10,productId:'',lotId:'',batch:'',expiry:'',locationId:'',quantity:1,unitCost:0,reason:'',expected:0})
const actionLabels:Record<StockCommand,string>={product:'Ajouter un produit',location:'Ajouter un emplacement',receipt:'Réceptionner un lot',transfer:'Transférer le stock',inventory:'Enregistrer un comptage',quarantine:'Mettre en quarantaine',recall:'Enregistrer un rappel',release:'Lever la quarantaine',waste:'Sortir vers les déchets'}
async function reload(){loading.value=true;error.value='';try{state.value=demoMode?loadStock(currentOffice.value.id):await request<StockState>('/stock/workspace');allowed.value=true}catch(e){allowed.value=false;state.value=emptyStock();error.value=(e as Error).message}finally{loading.value=false}}
watch(()=>currentOffice.value.id,()=>{open.value=false;detail.value=false;restoring.value=false;notice.value='';scanResult.value='';page.value=1;reload()},{immediate:true})
watch(tab,()=>{search.value='';page.value=1;detail.value=false;open.value=false;scanResult.value=''})
watch(search,()=>page.value=1)
const product=(id:string)=>state.value.products.find(p=>p.id===id)
const location=(id:string)=>state.value.locations.find(l=>l.id===id)?.name||'—'
const lot=(id:string)=>state.value.lots.find(l=>l.id===id)
const money=(n:number)=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'XOF',maximumFractionDigits:0}).format(n)
const physical=computed(()=>state.value.lots.reduce((n,l)=>n+l.quantity,0))
const available=computed(()=>state.value.lots.filter(eligible).reduce((n,l)=>n+l.quantity,0))
const value=computed(()=>state.value.lots.reduce((n,l)=>n+l.quantity*l.unitCost,0))
const alerts=computed(()=>state.value.lots.filter(l=>l.quantity>0&&l.expiry<=daysFromNow(90)).length)
const metrics=computed(()=>{
 const s=state.value,blocked=s.lots.filter(l=>l.quantity>0&&!eligible(l)),expired=s.lots.filter(l=>l.quantity>0&&l.expiry<=today())
 const sum=(kind:string)=>s.events.filter(e=>e.type===kind).reduce((n,e)=>n+Math.abs(e.quantity),0)
 const count=(kind:string)=>s.events.filter(e=>e.type===kind).length
 const shortages=s.products.filter(p=>fefo(s,p.id).reduce((n,l)=>n+l.quantity,0)<p.threshold).length
 const m=(label:string,value:string|number,note:string)=>({label,value,note})
 const all:Record<string,ReturnType<typeof m>[]>={
  produits:[m('Références au catalogue',s.products.length,'Produits de cette officine'),m('Sous le seuil indicatif',shortages,'Disponibilité par référence'),m('Unités disponibles',available.value,'Hors lots bloqués')],
  lots:[m('Lignes de lots',s.lots.length,'Répartition par emplacement'),m('Lignes disponibles',s.lots.filter(eligible).length,'Quantité positive et échéance future'),m('Lignes bloquées',blocked.length,'Avec stock physique')],
  fefo:[m('Produits avec lot éligible',s.products.filter(p=>fefo(s,p.id).length).length,'Une file distincte par produit'),m('Unités éligibles',available.value,'Aucune réservation appliquée'),m('Lignes exclues',s.lots.filter(l=>!eligible(l)).length,'Bloquées ou vides')],
  emplacements:[m('Emplacements',s.locations.length,'Zones définies dans la démo'),m('Emplacements avec stock',s.locations.filter(x=>s.lots.some(l=>l.locationId===x.id&&l.quantity>0)).length,'Au moins une ligne positive'),m('Unités réparties',physical.value,'Toutes les zones')],
  reception:[m('Réceptions enregistrées',count('receipt'),'Hors stock initial'),m('Unités réceptionnées',sum('receipt'),'Cumul des réceptions locales'),m('En quarantaine',s.lots.filter(l=>l.status==='quarantine'&&l.quantity>0).length,'Lignes à contrôler')],
  mouvements:[m('Événements du journal',s.events.length,'Stock initial inclus'),m('Transferts',count('transfer'),'Flux entre emplacements'),m('Corrections de comptage',count('inventory'),'Écarts historisés')],
  inventaires:[m('Comptages enregistrés',count('inventory'),'Chaque comptage produit une trace'),m('Lignes avec stock',s.lots.filter(l=>l.quantity>0).length,'Périmètre du comptage manuel'),m('Écarts absolus cumulés',sum('inventory'),'Unités, pas un solde net')],
  peremptions:[m('Échéance atteinte',expired.length,'Lots bloqués à la date du jour'),m('Dans les 30 prochains jours',s.lots.filter(l=>l.quantity>0&&l.expiry>today()&&l.expiry<=daysFromNow(30)).length,'Hors échéances déjà atteintes'),m('Valeur brute exposée',money(s.lots.filter(l=>l.quantity>0&&l.expiry<=daysFromNow(90)).reduce((n,l)=>n+l.quantity*l.unitCost,0)),'Échéance ≤90 jours, périmés inclus')],
  quarantaine:[m('Lignes en quarantaine',s.lots.filter(l=>l.status==='quarantine'&&l.quantity>0).length,'Contrôle ou anomalie'),m('Lignes rappelées',s.lots.filter(l=>l.status==='recalled'&&l.quantity>0).length,'Rappels internes'),m('Unités bloquées',blocked.reduce((n,l)=>n+l.quantity,0),'Péremptions incluses')],
  dechets:[m('Sorties enregistrées',count('waste'),'Mouvements locaux motivés'),m('Unités sorties',sum('waste'),'Pas une preuve de destruction'),m('Lots bloqués avec stock',blocked.length,'À examiner, pas à détruire automatiquement')],
  valorisation:[m('Valeur brute',money(value.value),'Coûts de réception indicatifs'),m('Valeur disponible',money(s.lots.filter(eligible).reduce((n,l)=>n+l.quantity*l.unitCost,0)),'Hors blocages'),m('Valeur bloquée',money(s.lots.filter(l=>!eligible(l)).reduce((n,l)=>n+l.quantity*l.unitCost,0)),'Sans dépréciation comptable')]
 }
 return all[tab.value]||[m('Unités physiques',physical.value,'Tous les emplacements'),m('Unités disponibles',available.value,'Hors blocages'),m('Échéances ≤90 jours',alerts.value,'Lignes de lots, périmés inclus')]
})
const primary=computed<StockCommand>(()=>({produits:'product',emplacements:'location',mouvements:'transfer',reception:'receipt',inventaires:'inventory',quarantaine:'quarantine',dechets:'waste'} as Record<string,StockCommand>)[tab.value]||'receipt')
const lotLabel=(id:string)=>{const l=lot(id);return l?`${product(l.productId)?.name} · ${l.batch} · ${location(l.locationId)}`:'—'}
interface TableRow {id:string;cells:string[];lotId?:string;productId?:string}
const headers=computed(()=>{
 if(tab.value==='produits')return ['Produit / code','Unité','Stock disponible','Seuil indicatif','État']
 if(tab.value==='emplacements')return ['Emplacement','Lignes de lots','Quantité physique','Valeur brute']
 if(['mouvements','reception','inventaires','dechets'].includes(tab.value))return ['Horodatage local','Opération','Lot / produit','Quantité / écart','Référence / motif']
 if(tab.value==='valorisation')return ['Produit','Quantité physique','Disponible','Valeur brute','Valeur bloquée']
 return ['Produit / lot','Péremption','Emplacement','Quantité','État']
})
const rows=computed<TableRow[]>(()=>{
 const s=state.value
 if(tab.value==='produits')return s.products.map(p=>{const q=fefo(s,p.id).reduce((n,l)=>n+l.quantity,0);return {id:p.id,productId:p.id,cells:[p.name+' · '+p.code,p.unit,String(q),String(p.threshold),q===0?'Rupture disponible':q<p.threshold?'Sous le seuil':'Stock disponible']}})
 if(tab.value==='emplacements')return s.locations.map(l=>{const lots=s.lots.filter(x=>x.locationId===l.id);return {id:l.id,cells:[l.name,String(lots.length),String(lots.reduce((n,x)=>n+x.quantity,0)),money(lots.reduce((n,x)=>n+x.quantity*x.unitCost,0))]}})
 if(['mouvements','reception','inventaires','dechets'].includes(tab.value)){
  const kind=({reception:'receipt',inventaires:'inventory',dechets:'waste'} as Record<string,string>)[tab.value]
  return s.events.filter(e=>!kind||e.type===kind).map(e=>({id:e.id,lotId:e.lotId||undefined,cells:[new Date(e.date).toLocaleString('fr-FR',{timeZone:'Africa/Porto-Novo'}),eventLabels[e.type]||e.type,lotLabel(e.lotId),String(e.quantity)+(e.from?' · '+location(e.from)+(e.to?' → '+location(e.to):''):''),e.reason]}))
 }
 if(tab.value==='valorisation')return s.products.map(p=>{const lots=s.lots.filter(l=>l.productId===p.id);return {id:p.id,productId:p.id,cells:[p.name,String(lots.reduce((n,l)=>n+l.quantity,0)),String(lots.filter(eligible).reduce((n,l)=>n+l.quantity,0)),money(lots.reduce((n,l)=>n+l.quantity*l.unitCost,0)),money(lots.filter(l=>!eligible(l)).reduce((n,l)=>n+l.quantity*l.unitCost,0))]}})
 let lots=[...s.lots]
 if(tab.value==='fefo')lots=lots.filter(eligible).sort((a,b)=>(product(a.productId)?.name||'').localeCompare(product(b.productId)?.name||'')||a.expiry.localeCompare(b.expiry)||a.id.localeCompare(b.id))
 if(tab.value==='peremptions'||tab.value==='overview')lots=lots.filter(l=>l.quantity>0&&l.expiry<=daysFromNow(90)).sort((a,b)=>a.expiry.localeCompare(b.expiry))
 if(tab.value==='quarantaine')lots=lots.filter(l=>l.status!=='available')
 return lots.map(l=>({id:l.id,lotId:l.id,cells:[product(l.productId)?.name+' · '+l.batch,l.expiry,location(l.locationId),String(l.quantity),l.expiry<=today()?'Bloqué · échéance atteinte':statusLabels[l.status]]}))
})
const filtered=computed(()=>rows.value.filter(r=>r.cells.join(' ').toLowerCase().includes(search.value.toLowerCase())))
const last=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10)))
const displayed=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10))
const selected=ref<TableRow|null>(null)
const selectedLot=computed(()=>selected.value?.lotId?lot(selected.value.lotId):undefined)
function inspectLot(id:string){const l=lot(id);if(!l)return;selected.value={id:l.id,lotId:l.id,cells:[product(l.productId)?.name+' · '+l.batch,l.expiry,location(l.locationId),String(l.quantity),statusLabels[l.status]]};detail.value=true}
function inspectProduct(id:string){const p=product(id);if(!p)return;selected.value={id:p.id,productId:p.id,cells:[p.name,p.code,p.unit]};detail.value=true}
function start(action:StockCommand,id?:string){operationKey.value=crypto.randomUUID();editingRevision.value=state.value.revision;command.value=action;dialogError.value='';confirmed.value=false;const l=id?lot(id):state.value.lots[0];form.value={name:'',code:'',unit:'Boîte',threshold:10,productId:state.value.products[0]?.id||'',lotId:l?.id||'',batch:'',expiry:daysFromNow(180),locationId:action==='transfer'?(state.value.locations.find(x=>x.id!==l?.locationId)?.id||''):(state.value.locations[0]?.id||''),quantity:action==='inventory'?(l?.quantity||0):1,expected:l?.quantity||0,unitCost:0,reason:''};open.value=true}
function changeLot(){const l=lot(form.value.lotId);form.value.expected=l?.quantity||0;if(command.value==='inventory')form.value.quantity=l?.quantity||0}
async function save(){if(!confirmed.value){dialogError.value='Confirmez explicitement cette opération.';notify('error',dialogError.value);return}busy.value=true;dialogError.value='';try{if(demoMode)state.value=saveStock(currentOffice.value.id,state.value,command.value,form.value);else await request('/stock/operations','POST',{request_key:operationKey.value,revision:editingRevision.value,confirmed:confirmed.value,command:command.value,input:form.value});open.value=false;detail.value=false;notice.value='';notify('success','Opération enregistrée.');page.value=1;if(!demoMode)await reload()}catch(e){dialogError.value=(e as Error).message;notify('error',dialogError.value)}finally{busy.value=false}}

function restore(){try{state.value=resetStock(currentOffice.value.id);error.value='';notice.value='';notify('success','Stock de cette officine rétabli.');restoring.value=false;page.value=1}catch(e){error.value=(e as Error).message;notify('error',error.value)}}
function lookup(){const p=state.value.products.find(p=>p.code.toLowerCase()===scan.value.trim().toLowerCase());if(!p){scanResult.value='not-found';notify('error','Code inconnu. Aucun produit créé automatiquement.');return}scanResult.value=p.id;notify('success',`${p.name} reconnu.`)}
function scanOpen(){const p=product(scanResult.value);if(p){selected.value={id:p.id,productId:p.id,cells:[p.name,p.code,p.unit]};detail.value=true}}
</script>
<template><section class="page erp-page stock-page"><div class="page-heading compact"><div><p class="eyebrow">PHARMACIE · STOCK & TRAÇABILITÉ</p><h1>{{title}}</h1><p class="page-subtitle">Lots, flux et contrôles · {{demoMode?currentOffice.name:'officine sélectionnée'}}</p></div><div v-if="allowed" class="heading-actions"><button class="button secondary" :disabled="loading||busy" @click="reload">Actualiser</button><button v-if="!['scan','fefo','peremptions','valorisation','lots'].includes(tab)" class="button primary" :disabled="!!error||loading||busy" @click="start(primary)"><AppIcon name="plus" :size="16"/>{{actionLabels[primary]}}</button></div></div>

<p v-if="loading" role="status" class="form-body">Chargement du stock…</p>
<div class="stock-content"><ModuleDemoContext v-if="demoMode"/><p v-if="error" class="alert error" role="alert">{{error}} <button type="button" @click="reload">Réessayer</button></p><template v-if="allowed&&!error&&!loading"><div v-if="tab!=='scan'" class="stats-grid"><div v-for="m in metrics" :key="m.label" class="stat-card"><span class="stat-top">{{m.label}}</span><strong>{{m.value}}</strong><span class="stat-note">{{m.note}}</span></div></div>
<StockDashboards :tab="tab" :state="state" @lot="inspectLot" @product="inspectProduct" @action="start"/>

<div v-if="tab==='scan'" class="panel form-body"><h2>Recherche par code produit</h2><p>Lecteur USB en mode clavier ou saisie manuelle, puis Entrée. Exemples : DEMO-001, DEMO-002. Décodage GS1/DataMatrix, caméra, numéros de série et vérification d’authenticité non implémentés.</p><form class="table-toolbar" @submit.prevent="lookup"><label class="search-field"><input v-model="scan" aria-label="Code produit scanné" placeholder="Saisir ou lire un code…" required maxlength="180"/></label><button class="button primary">Rechercher le code</button></form><div v-if="scanResult && scanResult!=='not-found'" class="detail-card"><strong>{{product(scanResult)?.name}}</strong><button class="button secondary" @click="scanOpen">Voir le produit</button></div></div>
<div v-else-if="!['fefo','emplacements','peremptions','quarantaine'].includes(tab)" class="panel"><div class="panel-heading"><div><h2>{{tab==='overview'?'Lots à surveiller':tab==='fefo'?'Ordre de sortie indicatif par produit':title}}</h2><p v-if="tab==='fefo'" class="page-subtitle">Date la plus proche d’abord · exclusion des lots à échéance atteinte, rappelés, en quarantaine ou vides.</p><p v-if="tab==='valorisation'" class="page-subtitle">Quantité × coût unitaire de réception. Valeurs bloquées incluses dans le brut ; pas de CUMP, FIFO comptable, fiscalité ni provision automatique.</p><p v-if="tab==='reception'" class="page-subtitle">Chaque réception crée un lot en quarantaine jusqu’au contrôle.</p><p v-if="tab==='inventaires'" class="page-subtitle">Comptage par lot et emplacement. Un écart crée une trace corrective ; il ne modifie pas les événements précédents.</p><p v-if="tab==='dechets'" class="page-subtitle">Sorties vers le circuit déchets uniquement. Ni certificat de destruction ni enlèvement prestataire.</p></div></div><div class="table-toolbar"><label class="search-field"><AppIcon name="search" :size="16"/><input v-model="search" aria-label="Rechercher dans le stock" placeholder="Rechercher dans cette rubrique…"/></label><span class="result-count">{{filtered.length}} résultat(s)</span></div><div class="table-scroll"><table><thead><tr><th v-for="h in headers" :key="h">{{h}}</th><th>ACTION</th></tr></thead><tbody><tr v-for="r in displayed" :key="r.id"><td v-for="(cell,i) in r.cells" :key="i"><span :class="i===0?'table-title':''">{{cell}}</span></td><td><button class="button secondary small" @click="selected=r;detail=true">Voir</button></td></tr><tr v-if="!displayed.length"><td :colspan="headers.length+1" class="empty-state">Aucun résultat pour cette rubrique et ces critères.</td></tr></tbody></table></div><div class="panel-heading"><button class="button secondary" :disabled="page<=1" @click="page--">Précédent</button><span>{{page}} / {{last}}</span><button class="button secondary" :disabled="page>=last" @click="page++">Suivant</button></div></div></template><div v-if="demoMode" class="panel-foot"><span>Exemples isolés par officine dans ce navigateur · aucune donnée patient.</span><button class="text-link" @click="restoring=true">Restaurer les exemples Stock</button></div></div>
<AppModal v-model="detail" title="Détail du stock" size="wide"><div v-if="selected" class="form-body"><dl class="application-summary"><template v-for="(cell,i) in selected.cells" :key="i"><dt>{{selected.lotId&&['fefo','emplacements','peremptions','quarantaine'].includes(tab)?['Produit / lot','Péremption','Emplacement','Quantité','État'][i]:tab==='scan'?['Produit','Code produit','Unité'][i]:headers[i]||'Information'}}</dt><dd style="white-space:pre-wrap">{{cell}}</dd></template></dl><template v-if="selectedLot"><p>Coût unitaire indicatif : {{money(selectedLot.unitCost)}} · {{statusLabels[selectedLot.status]}}</p><div class="heading-actions"><button class="button secondary" @click="start('transfer',selectedLot.id)">Transférer</button><button class="button secondary" @click="start('inventory',selectedLot.id)">Compter</button><button v-if="selectedLot.status==='available'" class="button secondary" @click="start('quarantine',selectedLot.id)">Mettre en quarantaine</button><button v-if="selectedLot.status==='quarantine'&&selectedLot.expiry>today()" class="button secondary" @click="start('release',selectedLot.id)">Lever la quarantaine</button><button v-if="selectedLot.status!=='recalled'" class="button secondary" @click="start('recall',selectedLot.id)">Simuler un rappel</button><button class="button secondary" @click="start('waste',selectedLot.id)">Sortir vers les déchets</button></div></template><template v-if="selected.productId"><h3>Lots de ce produit</h3><p v-for="l in state.lots.filter(l=>l.productId===selected?.productId)" :key="l.id">{{l.batch}} · {{location(l.locationId)}} · {{l.quantity}} · {{l.expiry}} · {{statusLabels[l.status]}}</p></template></div><template #footer><button class="button secondary" @click="detail=false">Fermer</button></template></AppModal>
<AppModal v-model="open" :title="actionLabels[command]" :busy="busy" size="wide"><form id="stock-operation" class="form-body form-grid" @submit.prevent="save"><p v-if="dialogError" class="alert error span-2" role="alert">{{dialogError}}</p><template v-if="command==='product'"><label>Nom du produit<input v-model="form.name" required maxlength="180"/></label><label>Code produit<input v-model="form.code" required maxlength="180"/></label><label>Unité de stock<input v-model="form.unit" required maxlength="180"/></label><label>Seuil indicatif<input v-model.number="form.threshold" required type="number" min="0" step="1"/></label></template><label v-else-if="command==='location'">Nom de l’emplacement<input v-model="form.name" required maxlength="180"/></label><template v-else><template v-if="command==='receipt'"><label>Produit<select v-model="form.productId" required><option v-for="p in state.products" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Numéro du lot<input v-model="form.batch" required maxlength="180"/></label><label>Péremption (date exacte)<input v-model="form.expiry" required type="date"/></label><label>Coût unitaire indicatif FCFA<input v-model.number="form.unitCost" required type="number" min="0" step="1"/></label><p class="module-disclaimer span-2">Date exacte exigée pour cet exemple ; les dates mois/année restent à définir. Réception en quarantaine, sans contrôle fournisseur ni commande d’achat connectés.</p></template><label v-else class="span-2">Lot / emplacement<select v-model="form.lotId" required @change="changeLot"><option v-for="l in state.lots" :key="l.id" :value="l.id">{{lotLabel(l.id)}} · {{l.quantity}}</option></select></label><label v-if="['receipt','transfer'].includes(command)">{{command==='transfer'?'Destination':'Emplacement'}}<select v-model="form.locationId" required><option v-for="l in state.locations" :key="l.id" :value="l.id">{{l.name}}</option></select></label><label v-if="['receipt','transfer','inventory','waste'].includes(command)">{{command==='inventory'?'Quantité physique comptée':'Quantité'}}<input v-model.number="form.quantity" required type="number" :min="command==='inventory'?0:1" step="1"/></label><p v-if="command==='inventory'" class="module-disclaimer span-2">Stock attendu au démarrage du comptage : {{form.expected}}. Un écart sera historisé et non écrasé silencieusement.</p><p v-if="['quarantine','recall','release'].includes(command)" class="alert span-2">S’applique à toutes les lignes de ce produit et numéro de lot dans cette officine. La levée d’un rappel n’est pas disponible. Aucun rappel externe n’est envoyé.</p></template><label class="span-2">Motif ou référence obligatoire<textarea v-model="form.reason" required maxlength="2000" rows="3"/></label><label class="checkbox-label span-2"><input v-model="confirmed" type="checkbox" required/>Je confirme cette opération {{demoMode?'sur les données fictives du navigateur':'dans le registre serveur de cette officine'}}.</label></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Annuler</button><button class="button primary" :disabled="busy" type="submit" form="stock-operation">Confirmer l’opération</button></template></AppModal>
<AppModal v-model="restoring" title="Rétablir le stock d’origine ?"><div class="form-body"><p>Les modifications locales du stock de {{currentOffice.name}} seront remplacées. Les autres officines ne seront pas modifiées.</p></div><template #footer><button class="button secondary" @click="restoring=false">Annuler</button><button class="button danger" @click="restore">Restaurer</button></template></AppModal></section></template>
<style scoped>
.stock-page .stat-card strong{font-size:26px}.stock-page .heading-actions{flex-wrap:wrap}.stock-page .panel-foot{gap:16px;flex-wrap:wrap}.stock-page td{max-width:320px;overflow-wrap:anywhere}
</style>
